function resize(svg,size){var n=String(size).replace(/[^0-9.]/g,'')||'56';return svg.replace(/width="64"/,'width="'+n+'"').replace(/height="64"/,'height="'+n+'"');}
function setLabel(svg,text){if(!text)return svg;return svg.replace(/aria-label="[^"]*"/,'aria-label="'+String(text).replace(/"/g,'&quot;')+'"');}
function getIcon(name,size,options){options=options||{};var variant=options.variant==='clean'?'clean':'premium';var svg=ICONS[variant][name];if(!svg)return null;
return setLabel(resize(svg,size||56),options.label||'');}
function hasIcon(name,variant){return Boolean(ICONS[variant==='clean'?'clean':'premium'][name]);}
window.IUMaster={ICONS:ICONS,getIcon:getIcon,hasIcon:hasIcon,keys:Object.keys(ICONS.premium)};
